R=[
("स्मोक्ड सैल्मन और खीरे के बाइट्स",
"अगर आपको बैगल और लॉक्स पसंद है, तो खीरे के स्लाइस पर स्मोक्ड सैल्मन और क्रीम चीज़ वाला यह कम कार्बोहाइड्रेट विकल्प आज़माएँ। ये मेहमाननवाज़ी के लिए बढ़िया स्टार्टर बनते हैं, या सिर्फ़ आपके लिए एक स्नैक!",
"6","4 खीरे के बाइट्स",
["1 बड़ा खीरा","1/4 कप ताज़ा डिल (बाँटकर)","4 औंस लाइट क्रीम चीज़","1 छोटा चम्मच नींबू का छिलका","1 छोटा चम्मच नींबू का रस","1/4 छोटा चम्मच काली मिर्च","4 औंस ठंडा स्मोक्ड सैल्मन (24 टुकड़ों में कटा हुआ)"],
["खीरे के सिरे काट दें। इसे लगभग 1/4 इंच मोटे 24 गोल टुकड़ों में काटें।","2 बड़े चम्मच डिल काटकर मध्यम कटोरे में डालें। बाकी डिल के डंठल हटाएँ और उसे छोटी टहनियों में अलग करें। टहनियों को एक तरफ़ रख दें।","कटे हुए डिल वाले मध्यम कटोरे में क्रीम चीज़, नींबू का छिलका और रस और काली मिर्च डालें।","क्रीम चीज़ के मिश्रण का लगभग 1 छोटा चम्मच हर खीरे के स्लाइस पर लगाएँ। हर एक के ऊपर सैल्मन का एक टुकड़ा रखें और डिल की एक टहनी से सजाएँ। थाली में सजाएँ और आनंद लें!"],[]),
("भुनी सब्ज़ियों का एनचिलाडा बेक",
"कैसरोल शैली का यह व्यंजन शाकाहारी विकल्प है और परिवार को बहुत पसंद आएगा!",
"6","कैसरोल का 1/6 हिस्सा",
["2 छोटे चम्मच कैनोला ऑयल या अपरिष्कृत मूँगफली का तेल","1 बड़ा मीठा प्याज़ (बारीक कटा हुआ)","1 कप हल्की या मध्यम तीखी टोमाटिलो सालसा (सालसा वेर्दे), अपनी पसंद की (बाँटकर)","1 पाउंड क्रेमिनी या सफ़ेद बटन मशरूम (कटे हुए)","1 साबुत पोब्लानो मिर्च (कटी हुई)","2 मध्यम पीली या नारंगी शिमला मिर्च (कटी हुई)","5 कप दबाकर भरा ताज़ा बेबी पालक (5 औंस)","1 कैन पिंटो बीन्स (15 औंस, धीरे से धोकर छानी हुई (1 1/2 कप))","3 बड़े चम्मच ताज़ा हरा धनिया (कटा हुआ)","1 छोटा चम्मच ताज़ी ओरेगानो की पत्तियाँ (बारीक कटी हुई)","1/2 छोटा चम्मच जीरा","1/4 छोटा चम्मच कोशर नमक","12 छोटी मक्के की टॉर्टिला (6 इंच)","1/2 कप मॉन्टेरी जैक या पेपर जैक चीज़ (2 औंस, कद्दूकस किया हुआ)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें।","एक बड़ी, गहरी नॉनस्टिक कड़ाही में मध्यम-तेज़ आँच पर तेल गरम करें। प्याज़ डालें और प्याज़ के नरम होने तक, लगभग 3 मिनट भूनें, फिर शिमला मिर्च डालें और नरम होने तक, 5 मिनट और भूनना जारी रखें। गर्मी सहने वाले कटोरे में निकाल लें।","कड़ाही में मशरूम डालें और नरम होने तक, लगभग 5 मिनट और भूनें। पालक डालें, और बस मुरझाने तक, लगभग 1 मिनट मिलाएँ। बीन्स, हरा धनिया, ओरेगानो, जीरा और नमक डालें, और पूरी तरह मिलने और गरम होने तक, लगभग 1 मिनट भूनें। शिमला मिर्च और प्याज़ मिलाएँ। मसाला ज़रूरत के अनुसार ठीक करें।","9x13 इंच की बेकिंग डिश में 1/2 कप सालसा फैलाएँ। डिश की तली को ढकने के लिए 6 टॉर्टिला सजाएँ। ऊपर से सब्ज़ी के मिश्रण का आधा हिस्सा बराबर फैलाएँ। बाकी 6 टॉर्टिला ऊपर सजाएँ। बचे हुए 1/2 कप सालसा से ढकें। ऊपर बाकी सब्ज़ी का मिश्रण बराबर फैलाएँ। चीज़ छिड़कें। पूरी तरह पकने और चीज़ के पिघलने तक, लगभग 20 मिनट बेक करें।","कैसरोल को 6 हिस्सों में काटें और परोसें।"],[]),
("अमरूद की सॉस के साथ भुने प्लांटेन और पोब्लानो मिर्च",
"यह मीठा, धुएँ की खुशबू वाला और नमकीन व्यंजन भुने सूअर के मांस या चिकन के साइड के रूप में एकदम सही है। प्लांटेन देखने में केले जैसे लगते हैं लेकिन उनमें स्टार्च ज़्यादा होता है और उन्हें भूनकर या पकाकर खाना सबसे अच्छा है। आप इन्हें आम तौर पर कैरिबियन या अफ़्रीकी व्यंजनों में पाएँगे, और ये अमेरिका की कई किराना दुकानों में उपलब्ध हैं।",
"8","1 टुकड़ा प्लांटेन + 1 बड़ा चम्मच सॉस",
["2 मध्यम प्लांटेन","2 साबुत एल्युमिनियम फ़ॉइल (शीट, प्लांटेन लपेटने लायक बड़ी)","1 मध्यम पोब्लानो मिर्च (1/4 इंच के क्यूब्स में कटी हुई)","1 छोटा चम्मच एवोकाडो ऑयल","3/4 कप चिकन स्टॉक (बिना नमक का)","1/4 कप शैलट (बारीक कटे हुए)","1 कली लहसुन (छिली और बारीक कटी हुई)","1/4 कप अमरूद के क्यूब्स (1/4 इंच के क्यूब्स)","1/4 कप राइस विनेगर","1/2 छोटा चम्मच कोशर नमक","1 छोटा चम्मच काली मिर्च (दरदरी)","1/2 कप केसो फ्रेस्को (चूरा किया हुआ)","2 छोटे चम्मच हरा धनिया (बारीक कटा हुआ)"],
["ओवन को 400°F पर पहले से गरम करें।","प्लांटेन के सिरे काट दें। एक छोटे चाकू की नोक को हर प्लांटेन में लगभग 1/2 इंच डालें और उसे ऊपर से नीचे तक चलाएँ। हर प्लांटेन को एक फ़ॉइल शीट में लपेटें। ओवन में 30 मिनट भूनें, फिर ओवन से निकालें और एक तरफ़ रख दें। ओवन चालू रखें।","पोब्लानो मिर्च को धोकर सुखाएँ। मिर्च की बाहरी सतह पर एवोकाडो ऑयल लगाएँ और (सावधानी से) उसे लौ पर या ओवन में तब तक रखें जब तक बाहर से जल न जाए। जब मिर्च जल जाए, तो उसे कटोरे में रखें और भाप से छिलका ढीला होने तक ढक दें। जले हुए हिस्से को हटाने के लिए मिर्च को ठंडे पानी के नीचे धोएँ, फिर उसे बारीक काटें।","छोटे सॉसपैन में स्टॉक, शैलट, लहसुन, पोब्लानो मिर्च और अमरूद डालें, और तेज़ उबाल पर लाएँ। चिकना पेस्ट बनने तक, लगभग 5 मिनट पकाएँ। राइस विनेगर, नमक और काली मिर्च डालें, और फेंटकर अच्छी तरह मिलाएँ ताकि सॉस में कोई गाँठ न रहे। आँच धीमी करें और 2 मिनट और पकाना जारी रखें। सॉस को ब्लेंडर में डालें और चिकना होने तक प्यूरी करें।","प्लांटेन से फ़ॉइल हटाएँ और हर एक को 4 बराबर चौथाई टुकड़ों में काटें। प्लांटेन को कटे हुए हिस्से से सावधानी से खोलें। 1 बड़ा चम्मच अमरूद की सॉस डालें, ऊपर केसो फ्रेस्को रखें, और हरे धनिये से सजाएँ। आनंद लें!"],[]),
("नमकीन अंडा और सब्ज़ी नाश्ते का बाउल",
"नाश्ते का बाउल आपके पास मौजूद अतिरिक्त सब्ज़ियों का उपयोग करने का अच्छा तरीका है। मसालों, चिकन सॉसेज, मशरूम और अंडों से इस बहुत कम कार्बोहाइड्रेट वाले बाउल को स्वाद की बढ़त मिलती है। तीखे स्वाद के लिए ऊपर थोड़ा नींबू का रस डालें।",
"2","2 अंडे + 1 सॉसेज + 1 1/2 कप सब्ज़ियाँ",
["1 कप अंडे का विकल्प","1/8 छोटा चम्मच स्मोक्ड पेपरिका","1/4 छोटा चम्मच लहसुन पाउडर","2 साबुत चिकन सॉसेज नाश्ते वाले लिंक","1/4 कप 1% वसा वाला, बिना नमक का कॉटेज चीज़","1/4 कप प्याज़ (कटा हुआ)","1/2 कप क्रेमिनी (बेबी बेला) मशरूम (कटे हुए)","1 कप बेबी पालक (कटा हुआ)","6 साबुत चेरी टमाटर (आधे कटे हुए)","1/2 साबुत एवोकाडो (कटा हुआ)","1 छोटा चम्मच ताज़े चाइव्स","1 छोटा चम्मच नींबू का रस (वैकल्पिक)"],
["एक नॉनस्टिक कड़ाही में मध्यम आँच पर अंडे का विकल्प चलाते हुए भुर्जी की तरह पकाएँ। पेपरिका और लहसुन पाउडर मिलाएँ।","एक मध्यम कड़ाही पर कुकिंग स्प्रे करें और मध्यम आँच पर गरम करें। सॉसेज लिंक डालें और भूरा होने तक पकाएँ। पैन से निकाल लें और प्याज़ और मशरूम डालें। भूरा होने तक, लगभग 5 मिनट पकाएँ। पालक डालें और बस मुरझाने तक पकाएँ। आँच से उतार लें।","अंडों को दो कटोरों में बाँटें। सॉसेज को काटें और हर कटोरे में एक लिंक रखें। बाकी हर चीज़ का आधा हिस्सा हर कटोरे में डालें: कॉटेज चीज़, पालक और मशरूम का मिश्रण, चेरी टमाटर और एवोकाडो। चाइव्स छिड़कें। चाहें तो नींबू के रस की बूँदें डालें।"],[]),
("फूलगोभी के चावल के साथ नींबू-थाइम झींगा स्टर-फ्राई",
"यह स्वादिष्ट नींबू-थाइम झींगा स्टर-फ्राई फूलगोभी के चावल और ताज़ी जड़ी-बूटियों जैसी मधुमेह के अनुकूल सामग्री का उपयोग करता है ताकि आपका रात का खाना आपके रक्त ग्लूकोज़ (ब्लड शुगर) के स्तर को न बढ़ाए। तीखे स्वादों और सेहतमंद सामग्री का आनंद लें जो स्वाद से समझौता किए बिना आपकी मधुमेह आहार योजना को सँभालने में मदद करेंगी। आप इस स्टर-फ्राई को चिकन जैसे अपने पसंदीदा प्रोटीन या टोफ़ू जैसे पौधे-आधारित विकल्प के साथ आसानी से अपने अनुसार बना सकते हैं। अगर आप झींगे का उपयोग करते हैं, तो सोडियम का स्तर कम रखने के लिए जमे हुए के बजाय ताज़े झींगे का उपयोग करने की कोशिश करें। आज ही यह आसान रेसिपी आज़माएँ!",
"4","2 कप",
["2 औंस ऑलिव ऑयल","2 कप मिली-जुली सब्ज़ियाँ (जैसे शिमला मिर्च, स्नैप मटर और गाजर) (कटी हुई)","2 साबुत हरा प्याज़ (स्प्रिंग ओनियन) (कटा हुआ)","2 कली लहसुन (बारीक कटी हुई)","1 पाउंड ताज़े (पहले जमाए हुए नहीं) बड़े झींगे (छिले हुए और नस निकाले हुए)","12 औंस जमी हुई चावल जैसी कटी फूलगोभी","1 बड़ा चम्मच सोया सॉस","1 बड़ा चम्मच ताज़ी थाइम की पत्तियाँ (साथ ही सजाने के लिए 4 टहनियाँ)","1 साबुत 1 नींबू का रस","1/8 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 साबुत नींबू (चार टुकड़ों में कटा हुआ, सजाने के लिए)"],
["एक बड़ी कड़ाही या वोक में मध्यम आँच पर ऑलिव ऑयल गरम करें। मिली-जुली सब्ज़ियाँ और कटा हरा प्याज़ कड़ाही में डालें। सब्ज़ियों के कुरकुरी-नरम होने तक 3–4 मिनट स्टर-फ्राई करें।","कटा हुआ लहसुन डालें और खुशबू आने तक 1–2 मिनट भूनें।","झींगे कड़ाही में डालें और उनके गुलाबी और अपारदर्शी होने तक लगभग 3–4 मिनट पकाएँ।","फूलगोभी के चावल कड़ाही में डालें। बीच-बीच में चलाते हुए, फूलगोभी के चावल के नरम होने तक, लगभग 3–4 मिनट पकाएँ।","सोया सॉस, ताज़ी थाइम की पत्तियाँ, नींबू का रस, नमक और काली मिर्च मिलाएँ। सब कुछ अच्छी तरह मिलाने और गरम करने के लिए चलाएँ।","चाहें तो ताज़ी थाइम की टहनियों और नींबू की फाँकों से सजाएँ।"],[]),
("बादाम क्रैनबेरी सेलेरी लॉग्स",
"बचपन के स्नैक \"एंट्स ऑन अ लॉग\" का नया रूप—यह बड़ों वाला रूप क्रीम चीज़, सूखे क्रैनबेरी और बादाम से बना है। हमने मिक्स्ड बेरी वाला व्हिप्ड क्रीम चीज़ इस्तेमाल किया, लेकिन सादा भी चलेगा। व्हिप्ड क्रीम चीज़ में वसा और कैलोरी कम होती है और फेंटने की प्रक्रिया की वजह से इसे लगाना आसान होता है। अपना पसंदीदा खोजने के लिए अलग-अलग सूखे फल और मेवे आज़माएँ!",
"4","3 टुकड़े",
["4 डंठल अजवाइन के डंठल/सेलेरी (धोए और छँटे हुए)","4 बड़े चम्मच मिक्स्ड बेरी व्हिप्ड क्रीम चीज़","24 साबुत सूखे क्रैनबेरी","12 साबुत बिना नमक के बादाम"],
["हर सेलेरी के डंठल में 1 बड़ा चम्मच क्रीम चीज़ भरें, फिर हर डंठल को 3 बराबर टुकड़ों में काटें। हर टुकड़े के ऊपर 1 बादाम और 2 सूखे क्रैनबेरी रखें। तुरंत परोसें, या ढककर परोसने तक फ्रिज में रखें।"],[]),
("चिली में भुने शैलट और ब्रसेल्स स्प्राउट",
"हल्के धुएँ की खुशबू और थोड़े तीखेपन के साथ, ये भुने शैलट और ब्रसेल्स स्प्राउट बनाने में आसान हैं। इन्हें भुने पोर्क लॉइन या बीफ़ टेंडरलॉइन के साथ परोसें।",
"9","1 कप",
["2 पाउंड शैलट (आधे कटे और छिले हुए)","2 बड़े चम्मच ऑलिव ऑयल (बाँटकर)","1/2 छोटा चम्मच चिली पाउडर","1/2 छोटा चम्मच नमक (बाँटकर)","2 पाउंड ब्रसेल्स स्प्राउट (धोए, छँटे और आधे कटे हुए)","1/4 छोटा चम्मच काली मिर्च","1/4 कप चिलगोज़े","1 शीट चर्मपत्र कागज़","2 छोटे चम्मच नींबू का छिलका"],
["ओवन को 400°F पर पहले से गरम करें। शैलट को उथली बेकिंग डिश में डालें। 1 बड़ा चम्मच तेल डालें और चिली पाउडर और आधे नमक के साथ परत चढ़ाएँ। डिश को फ़ॉइल से ढकें और 40 मिनट, या नरम होने तक भूनें। ढक्कन हटाएँ और 5 से 6 मिनट और बेक करना जारी रखें।","इस बीच, ब्रसेल्स स्प्राउट को काली मिर्च और बचे हुए तेल और नमक के साथ एक कटोरे में डालें। परत चढ़ाने के लिए मिलाएँ। ब्रसेल्स स्प्राउट को चर्मपत्र कागज़ या नॉनस्टिक फ़ॉइल बिछी बेकिंग शीट पर एक परत में फैलाएँ। स्प्राउट को 400°F पर 30 मिनट, या नरम होने तक भूनें।","परोसने के लिए, शैलट और ब्रसेल्स स्प्राउट को परोसने के कटोरे में मिलाएँ। ऊपर चिलगोज़े और नींबू का छिलका डालें।"],[]),
("किशमिश, 1 बड़ा चम्मच",
"1 बड़े चम्मच बिना चीनी वाली किशमिश की पोषण संबंधी जानकारी",
"1","1 बड़ा चम्मच",
["1 बड़ा चम्मच किशमिश (बिना चीनी वाली)"],[],[]),
("करंट और चिलगोज़े के साथ भुना बेबी पालक",
"यह भुना बेबी पालक झटपट बनने वाला और स्वादिष्ट साइड डिश है। पालक जल्दी पक जाता है और करंट की मिठास और चिलगोज़े का कुरकुरापन अपना लेता है। यह हरी पत्तेदार सब्ज़ियों को स्वादिष्ट और संतोषजनक बनाने का सरल तरीका है।",
"4","1/2 कप",
["1 छोटा चम्मच ऑलिव ऑयल","1 कली लहसुन (पतली कटी हुई)","1 पाउंड पालक","1 बड़ा चम्मच नींबू का रस (1/2 नींबू से)","1/2 बड़ा नींबू (4 फाँकों में कटा हुआ)","1 बड़ा चम्मच किशमिश या करंट","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च (वैकल्पिक)","1 बड़ा चम्मच चिलगोज़े (पैन में भुने हुए)"],
["एक बहुत बड़ी कड़ाही में मध्यम आँच पर तेल गरम करें। लहसुन डालें और उसके हल्का भूरा होना शुरू होने तक, लगभग 2 मिनट भूनें। लहसुन को एक छोटी प्लेट में निकालकर एक तरफ़ रख दें।","पालक को कड़ाही में एक बार में एक बड़ी मुट्ठी डालें। चिमटे से पकाएँ और पलटें जब तक सारा पालक बस मुरझा न जाए, लगभग 4 मिनट। नींबू का रस और करंट डालें, और मिलाने के लिए, लगभग 30 सेकंड पलटें। आँच से उतारें और नमक और, यदि उपयोग कर रहे हों, काली मिर्च छिड़कें।","चिमटे से पालक को परोसने के कटोरे या थाली में निकालें। ऊपर अलग रखे लहसुन के स्लाइस और चिलगोज़े डालें, और नींबू की फाँकों के साथ परोसें।"],[]),
("ट्रॉपिकल केल क्विनोआ सलाद",
"यह उन लोगों के लिए बढ़िया साइड है जिन्हें अन्यथा नमकीन व्यंजन में थोड़ा मीठा पसंद है। आप इस व्यंजन को पहले से बना सकते हैं और गरम या ठंडा परोस सकते हैं।",
"4","3/4 कप",
["3 बड़े चम्मच संतरे का रस","1 बड़ा चम्मच कटा हुआ ताज़ा अदरक","2 डंठल हरा प्याज़ (स्प्रिंग ओनियन) (कटा हुआ)","1/4 कप बादाम की कतरन","2 बड़े चम्मच बिना चीनी के नारियल के फ्लेक्स","1/2 (20 औंस) कैन बिना चीनी मिलाए रस में डिब्बाबंद अनानास के टुकड़े","6 कप कटी हुई ताज़ी केल","1 बड़ा चम्मच ऑलिव ऑयल","1/2 कप सूखा तिरंगा क्विनोआ"],
["ओवन को 350° F पर पहले से गरम करें।","क्विनोआ को पैकेट पर दिए निर्देशों के अनुसार, अलग से नमक डाले बिना पकाएँ।","नारियल और बादाम को बेकिंग शीट पर रखें और ओवन में लगभग 6 मिनट भूनें। जलने से बचाने के लिए हर 2 मिनट में चलाएँ।","एक नॉनस्टिक पैन में मध्यम-तेज़ आँच पर तेल गरम करें। केल और अनानास के टुकड़ों को लगभग 4 मिनट भूनें।","क्विनोआ, केल का मिश्रण, नारियल और बादाम, और बाकी सामग्री मिलाएँ। अच्छी तरह चलाएँ। बराबर मात्रा कटोरों में निकालें और अपनी पसंद के अनुसार गरम या ठंडा परोसें।"],[]),
]
